SELECT id, full_name, dept_id, manager_id, job_title, salary, hire_date, is_remote, DENSE_RANK() OVER w_part salary_dense_rank, RANK() OVER (PARTITION BY level ORDER BY salary DESC) salary_rank, AVG(salary) OVER (PARTITION BY level, dept_id ORDER BY hire_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) salary_avg_2_prior FROM employees WINDOW w_part AS (PARTITION BY dept_id, level ORDER BY salary)
